// External animation fixtures/oracles, never part of scene execution.
import assert from "node:assert/strict";
export const animatedPlottingCases = {
  coordinates: {
    factory: "createAnimatedCoordinatePlottingRenderer", source: "coordinate_plotting",
    output: "animated-coordinates", count: 17, duration: 5.1,
    boundaries: [0, 0.5, 1.3, 3.3, 4.3, 5.1], waits: [[4.3, 5.1]],
    checkpoints: [0, 0.25, 0.5, 0.9, 1.3, 1.8, 2.3, 3.3, 3.8, 4.3, 4.7, 5.1],
  },
  "number-line": {
    factory: "createAnimatedNumberLineRenderer", source: "animated_number_line",
    output: "animated-number-line", count: 22, duration: 8.8,
    boundaries: [0, 0.5, 1.5, 2, 3.5, 4, 5.2, 5.7, 6.5, 8, 8.8],
    waits: [[3.5, 4], [5.2, 5.7], [8, 8.8]],
    checkpoints: [0, 0.25, 0.5, 1, 1.5, 1.75, 2, 2.75, 3.5, 3.75, 4, 4.6,
      5.2, 5.45, 5.7, 6.1, 6.5, 7.25, 8, 8.4, 8.8],
  },
};

export function animatedPresentedTime(time, mode) {
  const example = animatedPlottingCases[mode];
  assert.ok(example && Number.isFinite(time) && time >= 0 && time <= example.duration,
    "invalid animated plotting sample");
  const interval = example.waits.find(([start, end]) => time > start && time <= end);
  return interval ? interval[0] : time;
}

function countColor(png, color) {
  let count = 0;
  for (let i = 0; i < png.data.length; i += 4) {
    if (color(png.data[i], png.data[i + 1], png.data[i + 2])) count++;
  }
  return count;
}
const blue = (r, g, b) => b > r + 35 && g > r + 20;
const yellow = (r, g, b) => r > b + 40 && g > b + 40;
export function assertAnimatedPlotPixels(png, time, mode, regionCount) {
  if (mode === "coordinates") {
    const bluePixels = countColor(png, blue), yellowPixels = countColor(png, yellow);
    if (time <= 1.3) assert.equal(bluePixels, 0, "curve appeared before Create");
    if (time <= 3.3) assert.equal(yellowPixels, 0, "data appeared before its Create");
    if (time >= 1.8) assert.ok(bluePixels > 100, "curve failed to reveal");
    if (time >= 3.8) assert.ok(yellowPixels > 100, "sampled data failed to reveal");
    // At the curve midpoint, its left portion exists and its far right does not.
    if (time === 2.3) {
      assert.ok(regionCount(png, -4, Math.sin(0.8) * 4 / 3, blue) > 2);
      assert.equal(regionCount(png, 4, Math.sin(7.2) * 4 / 3, blue), 0);
    }
    return;
  }
  if (time <= 1.5) assert.equal(countColor(png, yellow), 0, "marker appeared before FadeIn");
  if (time < 2) return;
  let x, y = 0;
  if (time <= 3.5) x = -4.4 + 4.4 * (time - 2) / 1.5;
  else if (time <= 4) x = 0;
  else if (time <= 5.2) x = 3.3 * (time - 4) / 1.2;
  else if (time <= 6.5) { x = 3.3; y = 0.6 * Math.max(0, (time - 5.7) / 0.8); }
  else { x = 3.3 - 5.5 * Math.min(1, (time - 6.5) / 1.5); y = 0.6; }
  assert.ok(regionCount(png, x, y, yellow) > 20,
    `marker missed NumberLine coordinate at ${time}: (${x}, ${y})`);
}

export function assertAnimatedPlotHolds(captures, mode) {
  for (const [start, end] of animatedPlottingCases[mode].waits) {
    const before = captures.find(capture => capture.time === start);
    assert.ok(before, "missing start-of-wait image");
    for (const after of captures.filter(capture => capture.time > start && capture.time <= end)) {
      assert.deepEqual(after.png.data, before.png.data, `wait changed the picture at ${after.time}`);
    }
  }
  if (mode === "coordinates") {
    const at = time => captures.find(capture => capture.time === time).png;
    assert.ok(countColor(at(2.3), blue) < countColor(at(3.3), blue) * 0.8,
      "Create must reveal the curve over time, not show the full path immediately");
  }
}

import assert from "node:assert/strict";
import test from "node:test";
import { readFile } from "node:fs/promises";
import { animatedPlottingCases, animatedPresentedTime } from "../scripts/animated-plotting-checks.mjs";
const read = name => readFile(new URL(name, import.meta.url), "utf8");

test("static qualification cannot accidentally consume an animated gallery source", async () => {
  const harness = await read("../scripts/plotting-qualification.mjs");
  assert.match(harness, /examples\/coordinate_plotting_static\.py/);
  const source = await read("./python/examples/coordinate_plotting_static.py");
  assert.doesNotMatch(source, /self\.(?:play|wait)\(/);
  assert.match(source, /self\.add\(axes, curve, data, title, label\)/);
});

test("both public animations run via a real continuation consumer in the paired gate", async () => {
  const harness = await read("../scripts/time-series-plotting-qualification.mjs");
  const workflow = await read("../.github/workflows/manim-plotting-qualification.yml");
  assert.match(harness, /onSemanticContinuation\(registration\)/);
  assert.match(harness, /sampleToAuthoredTime\(time\)/);
  for (const mode of Object.keys(animatedPlottingCases)) {
    assert.ok(workflow.includes(`time-series-plotting-qualification.mjs ${mode}`));
  }
});

test("quiet waits only retain their last visual timestamp inside declared wait intervals", () => {
  assert.equal(animatedPresentedTime(2.3, "coordinates"), 2.3);
  assert.equal(animatedPresentedTime(4.7, "coordinates"), 4.3);
  assert.equal(animatedPresentedTime(5.1, "coordinates"), 4.3);
  assert.equal(animatedPresentedTime(3.75, "number-line"), 3.5);
  assert.equal(animatedPresentedTime(6.1, "number-line"), 6.1);
  assert.equal(animatedPresentedTime(8.8, "number-line"), 8);
  for (const invalid of [NaN, -1, Infinity, 9]) {
    assert.throws(() => animatedPresentedTime(invalid, "number-line"));
  }
});
